module manuscript_reconstructor(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] fragment_data,\n    input wire fragment_valid,\n    input wire fragment_end,\n    input wire loading_done,\n    output reg [7:0] result_char,\n    output reg result_valid,\n    output reg result_done,\n    output reg ambiguous\n);\n\n// State declarations\nlocalparam [3:0] IDLE             = 4'd0;\nlocalparam [3:0] LOAD_FRAGMENTS   = 4'd1;\nlocalparam [3:0] CHECK_OVERLAPS   = 4'd2;\nlocalparam [3:0] BUILD_GRAPH      = 4'd3;\nlocalparam [3:0] TOPO_SORT        = 4'd4;\nlocalparam [3:0] DP_LONGEST_PATH  = 4'd5;\nlocalparam [3:0] FIND_MAX_PATH    = 4'd6;\nlocalparam [3:0] RECONSTRUCT_TEXT = 4'd7;\nlocalparam [3:0] OUTPUT_TEXT      = 4'd8;\nlocalparam [3:0] DONE_STATE       = 4'd9;\nlocalparam [3:0] INIT_CLEAR       = 4'd10;\n\n// Constants\nlocalparam [3:0] MAX_FRAGMENTS      = 8;\nlocalparam [4:0] MAX_FRAGMENT_LEN   = 16;\nlocalparam [4:0] OVERLAP_THRESHOLD  = 5;\nlocalparam [6:0] MAX_RESULT_LEN     = 128;\n\n// Internal registers\nreg [3:0] state, next_state;\nreg [2:0] fragment_count;\nreg [3:0] current_frag;\nreg [3:0] char_index;\nreg [3:0] i, j, k;  // General counters\n\n// Fragment storage\nreg [7:0] fragments [0:7][0:15];  // 8 fragments, 16 chars each\nreg [4:0] frag_lengths [0:7];     // Actual lengths\n\n// Overlap matrix\nreg [4:0] overlaps [0:7][0:7];\nreg [7:0] adjacency [0:7][0:7];\n\n// Topological sort\nreg [7:0] in_degree [0:7];\nreg [7:0] topological_order [0:7];\nreg [2:0] sort_index;\n\n// DP Arrays\nreg [15:0] longest_path [0:7];\nreg [1:0] path_count [0:7];\nreg [2:0] next_node [0:7];\n\n// Result reconstruction\nreg [7:0] result_buffer [0:127];\nreg [6:0] buf_length;\nreg [6:0] output_index;\nreg [2:0] current_node;\n\n// Cycle counters\nreg [9:0] safety_counter;\n\n// Topological sort and node processing flags\nreg [7:0] processed_nodes;\nreg [7:0] zero_in_degree;\n\n// Max path tracking\nreg [15:0] global_max;\nreg [2:0] max_count;\nreg [2:0] reconstruct_head;\n\n// Overlap comparison\nreg [4:0] test_overlap;\nreg overlap_match;\nreg [3:0] comp_idx;\n\n// FSM control\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= INIT_CLEAR;\n        fragment_count <= 3'd0;\n        current_frag <= 4'd0;\n        char_index <= 4'd0;\n        result_char <= 8'd0;\n        result_valid <= 1'b0;\n        result_done <= 1'b0;\n        ambiguous <= 1'b0;\n\n        // Clear arrays\n        for (i = 0; i < MAX_FRAGMENTS; i = i + 1) begin\n            frag_lengths[i] <= 5'd0;\n            longest_path[i] <= 16'd0;\n            path_count[i] <= 2'd0;\n            next_node[i] <= 3'd0;\n            in_degree[i] <= 8'd0;\n            topological_order[i] <= 8'd0;\n            for (j = 0; j < MAX_FRAGMENTS; j = j + 1) begin\n                overlaps[i][j] <= 5'd0;\n                adjacency[i][j] <= 8'd0;\n            end\n            for (j = 0; j < MAX_FRAGMENT_LEN; j = j + 1) begin\n                fragments[i][j] <= 8'd0;\n            end\n        end\n        for (i = 0; i < MAX_RESULT_LEN; i = i + 1) begin\n            result_buffer[i] <= 8'd0;\n        end\n        buf_length <= 7'd0;\n    end else begin\n        case (state)\n            INIT_CLEAR: begin\n                state <= IDLE;\n            end\n\n            IDLE: begin\n                result_done <= 1'b0;\n                result_valid <= 1'b0;\n                ambiguous <= 1'b0;\n                if (start) begin\n                    state <= LOAD_FRAGMENTS;\n                    current_frag <= 4'd0;\n                    char_index <= 4'd0;\n                    fragment_count <= 3'd0;\n                end\n            end\n\n            LOAD_FRAGMENTS: begin\n                if (loading_done) begin\n                    state <= CHECK_OVERLAPS;\n                    i <= 4'd0;\n                    j <= 4'd0;\n                end else if (fragment_valid) begin\n                    fragments[current_frag][char_index] <= fragment_data;\n                    char_index <= char_index + 4'd1;\n                end\n                if (fragment_end) begin\n                    frag_lengths[current_frag] <= char_index;\n                    current_frag <= current_frag + 4'd1;\n                    fragment_count <= fragment_count + 3'd1;\n                    char_index <= 4'd0;\n                end\n            end\n\n            CHECK_OVERLAPS: begin\n                if (i == fragment_count) begin\n                    state <= BUILD_GRAPH;\n                    i <= 4'd0;\n                end else begin\n                    if (j == fragment_count) begin\n                        j <= 4'd0;\n                        i <= i + 4'd1;\n                    end else begin\n                        if (i != j) begin\n                            test_overlap <= (frag_lengths[i] >= frag_lengths[j]) ? frag_lengths[j] : frag_lengths[i];\n                            comp_idx <= 4'd0;\n                            overlap_match <= 1'b1;\n                            state <= CHECK_OVERLAP_ITER;\n                        end else begin\n                            j <= j + 4'd1;\n                        end\n                    end\n                end\n            end\n\n            CHECK_OVERLAP_ITER: begin\n                // Edge conditions\n                if (test_overlap < OVERLAP_THRESHOLD || !overlap_match) begin\n                    if (test_overlap < OVERLAP_THRESHOLD) overlaps[i][j] <= 5'd0;\n                    j <= j + 4'd1;\n                    state <= CHECK_OVERLAPS;\n                end else begin\n                    // Check character comparison\n                    if (fragments[i][frag_lengths[i] - test_overlap + comp_idx] != fragments[j][comp_idx]) begin\n                        overlap_match <= 1'b0;\n                    end\n                    if (comp_idx == test_overlap - 1) begin\n                        overlaps[i][j] <= overlap_match ? test_overlap : 5'd0;\n                        test_overlap <= test_overlap - 1;\n                    end\n                    comp_idx <= comp_idx + 1;\n                end\n            end\n\n            BUILD_GRAPH: begin\n                if (i == fragment_count) begin\n                    state <= TOPO_SORT;\n                    i <= 4'd0;\n                    // Initialize in_degree\n                    for (j = 0; j < MAX_FRAGMENTS; j = j + 1) begin\n                        in_degree[j] <= 8'd0;\n                    end\n                end else begin\n                    if (j == fragment_count) begin\n                        j <= 4'd0;\n                        i <= i + 4'd1;\n                    end else begin\n                        adjacency[i][j] <= (overlaps[i][j] >= OVERLAP_THRESHOLD) ? 8'd1 : 8'd0;\n                        if (overlaps[i][j] >= OVERLAP_THRESHOLD) begin\n                            in_degree[j] <= in_degree[j] + 8'd1;\n                        end\n                        j <= j + 4'd1;\n                    end\n                end\n            end\n\n            TOPO_SORT: begin\n                // Implement Kahn's algorithm\n                zero_in_degree <= 8'd0;\n                for (k = 0; k < fragment_count; k = k + 1) begin\n                    if (in_degree[k] == 8'd0) begin\n                        zero_in_degree[k] <= 1'd1;\n                    end\n                end\n\n                sort_index <= fragment_count - 1;\n                state <= TOPO_SORT_PROCESS;\n            end\n\n            TOPO_SORT_PROCESS: begin\n                if (zero_in_degree == 8'd0) begin\n                    state <= DP_LONGEST_PATH;\n                    i <= fragment_count - 1;  // Process in reverse order\n                end else begin\n                    // Find first node with zero in-degree\n                    for (k = 0; k < MAX_FRAGMENTS; k = k + 1) begin\n                        if (zero_in_degree[k]) begin\n                            topological_order[sort_index] <= k;\n                            sort_index <= sort_index - 1;\n                            zero_in_degree[k] <= 1'd0;\n                            // Decrease in-degree of neighbors\n                            for (j = 0; j < fragment_count; j = j + 1) begin\n                                if (adjacency[k][j]) begin\n                                    in_degree[j] <= in_degree[j] - 8'd1;\n                                    if (in_degree[j] == 8'd0) begin\n                                        zero_in_degree[j] <= 1'd1;\n                                    end\n                                end\n                            end\n                            state <= TOPO_SORT_PROCESS;\n                        end\n                    end\n                end\n            end\n\n            DP_LONGEST_PATH: begin\n                if (i == -1) begin  // Underflow check for i\n                    state <= FIND_MAX_PATH;\n                end else begin\n                    current_node <= topological_order[i];\n                    for (j = 0; j < fragment_count; j = j + 1) begin\n                        if (adjacency[current_node][j]) begin\n                            if (longest_path[j] + overlaps[current_node][j] > longest_path[current_node]) begin\n                                longest_path[current_node] <= longest_path[j] + overlaps[current_node][j];\n                                next_node[current_node] <= j;\n                                path_count[current_node] <= path_count[j];\n                            end else if (longest_path[j] + overlaps[current_node][j] == longest_path[current_node]) begin\n                                // Saturate at 2 for ambiguity detection\n                                if (path_count[current_node] < 2'd2) begin\n                                    path_count[current_node] <= path_count[current_node] + 2'd1;\n                                end\n                            end\n                        end\n                    end\n                    i <= i - 1;\n                end\n            end\n\n            FIND_MAX_PATH: begin\n                global_max <= 16'd0;\n                max_count <= 3'd0;\n                reconstruct_head <= 3'd0;\n                for (i = 0; i < fragment_count; i = i + 1) begin\n                    if (longest_path[i] > global_max) begin\n                        global_max <= longest_path[i];\n                        reconstruct_head <= i;\n                        max_count <= 1;\n                    end else if (longest_path[i] == global_max) begin\n                        max_count <= max_count + 1;\n                    end\n                end\n                ambiguous <= (max_count > 1) ? 1'b1 : 1'b0;\n                state <= RECONSTRUCT_TEXT;\n                current_node <= reconstruct_head;\n            end\n\n            RECONSTRUCT_TEXT: begin\n                // Copy first fragment\n                for (i = 0; i < frag_lengths[current_node]; i = i + 1) begin\n                    result_buffer[i] <= fragments[current_node][i];\n                end\n                buf_length <= frag_lengths[current_node];\n                current_node <= next_node[current_node];\n                state <= RECONSTRUCT_LOOP;\n            end\n\n            RECONSTRUCT_LOOP: begin\n                if (current_node != reconstruct_head) begin  // Break condition?\n                    for (i = 0; i < frag_lengths[current_node] - overlaps[next_node[current_node]][current_node]; i = i + 1) begin\n                        result_buffer[buf_length + i] <= fragments[current_node][overlaps[next_node[current_node]][current_node] + i];\n                    end\n                    buf_length <= buf_length + frag_lengths[current_node] - overlaps[next_node[current_node]][current_node];\n                    current_node <= next_node[current_node];\n                end else begin\n                    output_index <= 7'd0;\n                    state <= OUTPUT_TEXT;\n                end\n            end\n\n            OUTPUT_TEXT: begin\n                if (output_index == buf_length) begin\n                    result_valid <= 1'b0;\n                    result_done <= 1'b1;\n                    state <= DONE_STATE;\n                end else begin\n                    result_char <= result_buffer[output_index];\n                    result_valid <= 1'b1;\n                    output_index <= output_index + 1;\n                end\n            end\n\n            DONE_STATE: begin\n                result_done <= 1'b1\n                if (safety_counter == 10'd1000) state <= IDLE;  // Fallback\n                safety_counter <= safety_counter + 1;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule